// ========================================================================= // 6. ROUTER & APPLICATION BOOTSTRAP // ========================================================================= const STORAGE_LANG_KEY = "dlbd_visitor_lang"; const STORAGE_READ_NOTIFS_KEY = "dlbd_visitor_read_notifs"; let currentLang = localStorage.getItem(STORAGE_LANG_KEY) === "en" ? "en" : "bn"; let notifFilterType = "ALL"; let toastTimer = null;
function loadReadIds() { try { const r = JSON.parse(localStorage.getItem(STORAGE_READ_NOTIFS_KEY) || "[]"); return new Set(Array.isArray(r) ? r.map(String) : []); } catch { return new Set(); } } let readNotifIds = loadReadIds(); function saveReadIds() { try { localStorage.setItem(STORAGE_READ_NOTIFS_KEY, JSON.stringify(Array.from(readNotifIds).slice(-300))); } catch {} }
function shouldUseHashRouting() { return true; }
function normalizePath(p) { let clean = String(p || "/").trim(); if (!clean.startsWith("/")) clean = "/" + clean; if (/\/(index|visitor)\.html$/i.test(clean)) clean = "/"; if (clean.length > 1 && clean.endsWith("/")) clean = clean.slice(0, -1); return clean || "/"; }
function getCurrentRoute() { if (shouldUseHashRouting() || window.location.hash.startsWith("#/")) { const rawHash = (window.location.hash || "#/").replace(/^#/, "") || "/"; const [pathPart, queryPart = ""] = rawHash.split("?"); return { pathname: normalizePath(pathPart), params: new URLSearchParams(queryPart) }; } return { pathname: normalizePath(window.location.pathname), params: new URLSearchParams(window.location.search) }; }
function navigate(targetUrl) { const dest = String(targetUrl || "/"); if (shouldUseHashRouting()) { const hashDest = "#" + (dest.startsWith("/") ? dest : "/" + dest); if (window.location.hash !== hashDest) window.location.hash = hashDest; else renderCurrentRoute(); } else { window.history.pushState(null, "", dest); renderCurrentRoute(); } window.scrollTo({ top: 0, behavior: "smooth" }); }
function showToast(msg) { const toastEl = document.getElementById("siteToast"); if (!toastEl) return; toastEl.textContent = msg; toastEl.classList.remove("hidden"); if (toastTimer) clearTimeout(toastTimer); toastTimer = setTimeout(() => toastEl.classList.add("hidden"), 2800); }
async function shareProfile(title, text) { const url = window.location.href; try { if (navigator.share) return await navigator.share({ title, text, url }); if (navigator.clipboard?.writeText) { await navigator.clipboard.writeText(url); return showToast(t(currentLang, "toast_link_copied")); } showToast(t(currentLang, "toast_share_failed")); } catch (err) { if (err?.name !== "AbortError") showToast(t(currentLang, "toast_share_failed")); } }
