") { const lines = currentLang === "bn" ? ["Doctor List BD একটি তথ্যমূলক স্বাস্থ্যসেবা ডিরেক্টরি; সরাসরি চিকিৎসা সেবা প্রদান করে না।", "ভিজিটের আগে ফোনে চেম্বারের সময়সূচী ও ফি নিশ্চিত হয়ে নিন।", "জরুরি অবস্থায় নিকটস্থ হাসপাতালের জরুরি বিভাগে যোগাযোগ করুন।"] : ["Doctor List BD is an informational healthcare directory and does not provide direct medical treatment.", "Please confirm chamber timings and consultation fees by phone before visiting.", "In an emergency, contact your nearest hospital emergency department immediately."]; mainEl.replaceChildren(renderStaticPage("terms_title", "terms_sub", "nav_terms", [el("h2", { text: t(currentLang, "terms_title") }), el("ul", {}, lines.map((l) => el("li", { text: l })))], ctx)); return applySeo({ title: `${t(currentLang, "terms_title")} | Doctor List BD`, description: t(currentLang, "terms_sub"), path: "/terms" }); }
