function closeAllDrawers() { document.getElementById("mobileDrawer")?.classList.remove("open"); document.getElementById("mobileDrawerBackdrop")?.classList.add("hidden"); document.getElementById("mobileMenuBtn")?.setAttribute("aria-expanded", "false"); document.getElementById("notifDrawer")?.classList.remove("open"); document.getElementById("notifBackdrop")?.classList.add("hidden"); document.getElementById("notifToggleBtn")?.setAttribute("aria-expanded", "false"); }
function wireEvents() { document.addEventListener("click", (e) => { const link = e.target.closest("a[data-nav]"); if (!link || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return; e.preventDefault(); closeAllDrawers(); navigate(link.getAttribute("data-nav") || "/"); });
document.querySelectorAll(".lang-opt").forEach((btn) => { btn.addEventListener("click", () => { const next = btn.dataset.lang === "en" ? "en" : "bn"; if (next === currentLang) return; currentLang = next; try { localStorage.setItem(STORAGE_LANG_KEY, currentLang); } catch {} renderCurrentRoute(); }); });
document.getElementById("mobileMenuBtn")?.addEventListener("click", () => { closeAllDrawers(); document.getElementById("mobileDrawer")?.classList.add("open"); document.getElementById("mobileDrawerBackdrop")?.classList.remove("hidden"); }); document.getElementById("mobileDrawerClose")?.addEventListener("click", closeAllDrawers); document.getElementById("mobileDrawerBackdrop")?.addEventListener("click", closeAllDrawers);
document.getElementById("notifToggleBtn")?.addEventListener("click", () => { closeAllDrawers(); refreshNotificationsUI(); document.getElementById("notifDrawer")?.classList.add("open"); document.getElementById("notifBackdrop")?.classList.remove("hidden"); }); document.getElementById("notifDrawerClose")?.addEventListener("click", closeAllDrawers); document.getElementById("notifBackdrop")?.addEventListener("click", closeAllDrawers);
document.getElementById("markAllReadBtn")?.addEventListener("click", () => { for (const n of directoryStore.state.notifications || []) readNotifIds.add(n.id); saveReadIds(); refreshNotificationsUI(); showToast(t(currentLang, "toast_marked_read")); });
document.getElementById("notifFilterTabs")?.addEventListener("click", (e) => { const chip = e.target.closest("button[data-ntype]"); if (!chip) return; notifFilterType = chip.dataset.ntype || "ALL"; document.querySelectorAll("#notifFilterTabs .chip").forEach((c) => c.classList.toggle("active", c === chip)); refreshNotificationsUI(); });
const searchInput = document.getElementById("globalSearchInput"); const clearBtn = document.getElementById("globalSearchClear"); const dropdown = document.getElementById("globalSearchDropdown"); const searchWrap = document.getElementById("headerSearchWrap"); const hideDropdown = () => dropdown?.classList.add("hidden");
const runAuto = () => { const q = (searchInput?.value || "").trim(); clearBtn?.classList.toggle("hidden", !q); if (!q || !dropdown) return hideDropdown(); renderAutocompleteDropdown(dropdown, directoryStore.searchUnified(q), { lang: currentLang, navigate, onSelect: () => { hideDropdown(); if (searchInput) searchInput.value = ""; clearBtn?.classList.add("hidden"); } }); dropdown.classList.remove("hidden"); };
const submitSearch = () => { const q = (searchInput?.value || "").trim(); hideDropdown(); navigate(q ? `/doctors?q=${encodeURIComponent(q)}` : "/doctors"); };
searchInput?.addEventListener("input", runAuto); searchInput?.addEventListener("focus", () => { if ((searchInput.value || "").trim()) runAuto(); }); searchInput?.addEventListener("keydown", (e) => { if (e.key === "Enter") { e.preventDefault(); submitSearch(); } else if (e.key === "Escape") hideDropdown(); }); clearBtn?.addEventListener("click", () => { if (searchInput) { searchInput.value = ""; searchInput.focus(); } clearBtn.classList.add("hidden"); hideDropdown(); }); document.getElementById("globalSearchSubmit")?.addEventListener("click", submitSearch); document.addEventListener("click", (e) => { if (searchWrap && !searchWrap.contains(e.target)) hideDropdown(); }); document.addEventListener("keydown", (e) => { if (e.key === "Escape") { closeAllDrawers(); hideDropdown(); } });
window.addEventListener("popstate", renderCurrentRoute); window.addEventListener("hashchange", renderCurrentRoute); }
const visitorCounterState = { online: 1, today: 0, month: 0, allTime: 0 };
function renderVisitorCounterNumbers() { const setNum = (id, val) => { const node = document.getElementById(id); if (node) node.textContent = formatNumber(Math.max(0, Number(val) || 0), currentLang); }; setNum("vcOnline", Math.max(1, visitorCounterState.online)); setNum("vcToday", visitorCounterState.today); setNum("vcMonth", visitorCounterState.month); setNum("vcAllTime", visitorCounterState.allTime); }
function getBangladeshDateKeys() { const bdNow = new Date(Date.now() + 6 * 60 * 60 * 1000); const y = bdNow.getUTCFullYear(); const m = String(bdNow.getUTCMonth() + 1).padStart(2, "0"); const d = String(bdNow.getUTCDate()).padStart(2, "0"); return { todayKey: `${y}-${m}-${d}`, monthKey: `${y}-${m}` }; }
function initLiveVisitorCounter() { try { const db = getPublicDatabase(); const basePath = "directory/ad_analytics/web_visitors"; const { todayKey, monthKey } = getBangladeshDateKeys(); const todayRef = ref(db, `${basePath}/daily/${todayKey}`); const monthRef = ref(db, `${basePath}/monthly/${monthKey}`); const allTimeRef = ref(db, `${basePath}/allTime`); const onlineListRef = ref(db, `${basePath}/online`);
onValue(todayRef, (snap) => { visitorCounterState.today = Number(snap.val()) || 0; renderVisitorCounterNumbers(); }); onValue(monthRef, (snap) => { visitorCounterState.month = Number(snap.val()) || 0; renderVisitorCounterNumbers(); }); onValue(allTimeRef, (snap) => { visitorCounterState.allTime = Number(snap.val()) || 0; renderVisitorCounterNumbers(); }); onValue(onlineListRef, (snap) => { const val = snap.val(); const now = Date.now(); let active = 0; if (val && typeof val === "object") { for (const entry of Object.values(val)) { const ts = typeof entry === "number" ? entry : Number(entry?.ts || 0); if (!ts || now - ts < 15 * 60 * 1000) active += 1; } } visitorCounterState.online = Math.max(1, active); renderVisitorCounterNumbers(); });
const visitKey = `dlbd_web_counted_${todayKey}`; let alreadyCounted = false; try { alreadyCounted = sessionStorage.getItem(visitKey) === "1"; } catch {} if (!alreadyCounted) { try { sessionStorage.setItem(visitKey, "1"); } catch {} const inc = (cur) => (Number(cur) || 0) + 1; runTransaction(todayRef, inc).catch(() => {}); runTransaction(monthRef, inc).catch(() => {}); runTransaction(allTimeRef, inc).catch(() => {}); }
const sessionId = `s_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 9)}`; const presenceRef = ref(db, `${basePath}/online/${sessionId}`); onValue(ref(db, ".info/connected"), (snap) => { if (snap.val() !== true) return; onDisconnect(presenceRef).remove().catch(() => {}); set(presenceRef, { ts: Date.now() }).catch(() => {}); }); const hb = setInterval(() => { if (document.visibilityState === "visible") set(presenceRef, { ts: Date.now() }).catch(() => {}); }, 3 * 60 * 1000); window.addEventListener("pagehide", () => { clearInterval(hb); remove(presenceRef).catch(() => {}); }); } catch {} }
wireEvents(); applyChromeTranslations(); directoryStore.subscribe(() => renderCurrentRoute()); directoryStore.start(); initLiveVisitorCounter();
